import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/math-sum-diff-adv.svg",g=JSON.parse('{"title":"小学奥数进阶：和差问题深度解析","description":"在掌握基础和差问题的基础上，本文带你深入探讨复杂的变式和差问题，通过图解法和份数思维，攻克应用题难关。","frontmatter":{"title":"小学奥数进阶：和差问题深度解析","date":"2026-02-08T09:00:00.000Z","categories":["数学"],"tags":["小学数学","奥数","和差问题"],"description":"在掌握基础和差问题的基础上，本文带你深入探讨复杂的变式和差问题，通过图解法和份数思维，攻克应用题难关。","cover":"/img/math-sum-diff-adv.svg","top_img":"/img/math-sum-diff-adv.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-sum-diff-adv.md","filePath":"posts/primary-math-olympiad-sum-diff-adv.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-sum-diff-adv.md"};function r(o,a,e,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="小学奥数进阶-和差问题深度解析" tabindex="-1">小学奥数进阶：和差问题深度解析 <a class="header-anchor" href="#小学奥数进阶-和差问题深度解析" aria-label="Permalink to &quot;小学奥数进阶：和差问题深度解析&quot;">​</a></h1><h2 id="一、-核心思想回顾" tabindex="-1">一、 核心思想回顾 <a class="header-anchor" href="#一、-核心思想回顾" aria-label="Permalink to &quot;一、 核心思想回顾&quot;">​</a></h2><p>和差问题是指已知两个数的<strong>和</strong>与这两个数的<strong>差</strong>，求这两个数。</p><ul><li><strong>大数 = (和 + 差) ÷ 2</strong></li><li><strong>小数 = (和 - 差) ÷ 2</strong></li></ul><h3 id="图解逻辑" tabindex="-1">图解逻辑 <a class="header-anchor" href="#图解逻辑" aria-label="Permalink to &quot;图解逻辑&quot;">​</a></h3><p><img src="'+p+'" alt="和差问题进阶图解"></p><p>通过线段图可以直观看到：</p><ol><li>和加上差，正好是两个大数。</li><li>和减去差，正好是两个小数。</li></ol><hr><h2 id="二、-进阶变式-隐藏的-和-与-差" tabindex="-1">二、 进阶变式：隐藏的“和”与“差” <a class="header-anchor" href="#二、-进阶变式-隐藏的-和-与-差" aria-label="Permalink to &quot;二、 进阶变式：隐藏的“和”与“差”&quot;">​</a></h2><p>在奥数题中，题目往往不会直接给出和与差，需要我们通过条件推导。</p><h3 id="_1-传递后的-相等" tabindex="-1">1. 传递后的“相等” <a class="header-anchor" href="#_1-传递后的-相等" aria-label="Permalink to &quot;1. 传递后的“相等”&quot;">​</a></h3><p><strong>例题</strong>：甲、乙两筐苹果共 64 千克。如果从甲筐取出 8 千克放入乙筐，两筐苹果的重量就相等了。求甲、乙两筐原来各有多少千克苹果？</p><p><strong>解析</strong>：</p><ul><li><strong>找和</strong>：两筐共 64 千克，即 <strong>和 = 64</strong>。</li><li><strong>找差</strong>：甲给乙 8 千克后相等。这意味着甲原来比乙多 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">8 \\times 2 = 16</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span></span></span></span> 千克（因为甲少了 8，乙多了 8，差距缩小了 16 才相等）。即 <strong>差 = 16</strong>。</li><li><strong>计算</strong>： <ul><li>甲（大数）= <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>6</mn><mn>4</mn><mo>+</mo><mn>1</mn><mn>6</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">(64 + 16) \\div 2 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>（千克）</li><li>乙（小数）= <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>6</mn><mn>4</mn><mo>−</mo><mn>1</mn><mn>6</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">(64 - 16) \\div 2 = 24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span>（千克）</li></ul></li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>0</mn><mo>+</mo><mn>2</mn><mn>4</mn><mo>=</mo><mn>6</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">40 + 24 = 64</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">4</span></span></span></span>；<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>0</mn><mo>−</mo><mn>8</mn><mo>=</mo><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">40 - 8 = 32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>4</mn><mo>+</mo><mn>8</mn><mo>=</mo><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">24 + 8 = 32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span>，相等！</li></ul><h3 id="_2-三个数的和差" tabindex="-1">2. 三个数的和差 <a class="header-anchor" href="#_2-三个数的和差" aria-label="Permalink to &quot;2. 三个数的和差&quot;">​</a></h3><p><strong>例题</strong>：甲乙丙三人共有 90 张卡片。甲比乙多 5 张，乙比丙多 10 张。问三人各有多少张？</p><p><strong>解析</strong>：</p><ul><li>我们可以把所有人都向“乙”看齐，或者都向“丙”看齐。</li><li><strong>以丙为基准（小数）</strong>： <ul><li>丙是 1 份。</li><li>乙 = 丙 + 10。</li><li>甲 = 乙 + 5 = 丙 + 10 + 5 = 丙 + 15。</li></ul></li><li><strong>求和</strong>：丙 + (丙 + 10) + (丙 + 15) = 90。</li><li>3 \\times 丙 + 25 = 90 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 3 \\times 丙 = 65（发现除不尽？检查题目：应该是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>0</mn><mo>−</mo><mn>2</mn><mn>5</mn><mo>=</mo><mn>6</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">90 - 25 = 65</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">5</span></span></span></span>。如果是 91 呢？或者修改题目：甲比乙多 10，乙比丙多 5）。</li><li><strong>修正题目数值</strong>：甲比乙多 5，乙比丙多 10，总数 100。 <ul><li>3 \\times 丙 + 25 = 100 \\rightarrow 3 \\times 丙 = 75 \\rightarrow 丙 = 25。</li><li>乙 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>5</mn><mo>+</mo><mn>1</mn><mn>0</mn><mo>=</mo><mn>3</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">25 + 10 = 35</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span></span></span></span>。</li><li>甲 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>5</mn><mo>+</mo><mn>5</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">35 + 5 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>。</li></ul></li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>0</mn><mo>+</mo><mn>3</mn><mn>5</mn><mo>+</mo><mn>2</mn><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">40 + 35 + 25 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li></ul><hr><h2 id="三、-总结提升" tabindex="-1">三、 总结提升 <a class="header-anchor" href="#三、-总结提升" aria-label="Permalink to &quot;三、 总结提升&quot;">​</a></h2><p>解决复杂和差问题的关键是：<strong>画线段图</strong>。</p><ol><li>确定一个数为“基准”。</li><li>把其他数通过“差”的关系表示出来。</li><li>利用“总和”建立等式求解。</li></ol><hr><h2 id="四、-举一反三-练习题" tabindex="-1">四、 举一反三（练习题） <a class="header-anchor" href="#四、-举一反三-练习题" aria-label="Permalink to &quot;四、 举一反三（练习题）&quot;">​</a></h2><ol><li>两层书架共有书 120 本。如果从上层搬 15 本到下层，下层还比上层少 10 本。求两层原来各有多少本书？</li><li>甲乙两个仓库共存粮 80 吨。如果从甲仓运出 10 吨，乙仓运进 6 吨，两个仓库的粮食就一样多了。求甲乙两仓原来各存粮多少吨？</li></ol><hr><p><em>提示：画图是解题的第一步！</em></p>',28)])])}const u=s(l,[["render",r]]);export{g as __pageData,u as default};
